corrected_code:
const { Queue } = require('bullmq');
const payrollQueue = new Queue('payroll-payouts', { connection: redisClient });

app.post('/api/payroll/queue-payout', verifyJwt, async (req, res) => {
  const { companyId, batchId } = req.body;
  const isAuthorized = await CompanyRole.findOne({
    where: { companyId, userId: req.user.id, role: 'PAYROLL_ADMIN' }
  });
  if (!isAuthorized) {
    return res.status(403).json({ error: 'You are not authorized to trigger payroll for this company' });
  }
  const job = await payrollQueue.add('execute-payout', {
    companyId,
    batchId,
    submittedBy: req.user.id
  });
  res.status(202).json({ queued: true, jobId: job.id });
});
